verification_commands.ac4:
set -u
A=docs/state/outputs/t121_definer_gate_amendment.json
test -f "$A" || { echo "ac4 RED: $A missing - the proposal is the written record the merge window applies"; exit 1; }
python3 - "$A" <<'PYEOF' || exit 1
import json, hashlib, sys
rec = json.load(open(sys.argv[1], encoding="utf-8"))
raw = open("docs/state/merge_test_index.json", "rb").read()
tests = json.loads(raw.decode("utf-8"))["tests"]
def csha(s): return hashlib.sha256(s.encode()).hexdigest()
def esha(x): return hashlib.sha256(json.dumps(x, separators=(",", ":")).encode()).hexdigest()
fail = []
if rec.get("status") != "proposed":
    fail.append("amendment status is %r, not 'proposed' - the definer proposes, the orchestrator applies" % rec.get("status"))
if rec.get("card_writes_index_bytes") is not False:
    fail.append("card_writes_index_bytes must be False")
if len(tests) != 318 or hashlib.sha256(raw).hexdigest() != "e98f96bd7b7241458cf9f1d3c397730afd08af64564448fb579213bd29469b2b":
    fail.append("live index is not the 318-entry e98f96bd base the pins were struck against - re-pin before applying")
am = [a for a in rec["amendments"] if a["index"] == 227][0]
cmd = tests[227]["command"]
if csha(cmd) != am["old_command_sha256"] or len(cmd) != am["old_command_len"]:
    fail.append("old_command_sha256/len do not match the live leg 227")
if esha(tests[227]) != am["entry_sha_before"]:
    fail.append("entry_sha_before does not match the live entry")
built = cmd
for reg in am["replaced_regions"]:
    n = cmd.count(reg["from"])
    if n != 1:
        fail.append("region from-string occurs %d times (must be exactly 1): %r" % (n, reg["from"][:48]))
    built = built.replace(reg["from"], reg["to"], 1)
back = built
for reg in reversed(am["replaced_regions"]):
    back = back.replace(reg["to"], reg["from"], 1)
if back != cmd:
    fail.append("region replacement is not reverse-lossless")
if csha(built) != am["new_command_sha256"] or len(built) != am["new_command_len"]:
    fail.append("new_command_sha256/len do not reconstruct from the regions")
import copy
e2 = copy.deepcopy(tests[227]); e2["command"] = built
if esha(e2) != am["entry_sha_after"]:
    fail.append("entry_sha_after does not reconstruct from the built entry")
settled = built
for ph, val in [("<T121_README_CR_STRIPPED_DIGEST_64HEX>", "77cbdd64d901cef65430c73d4145d96962535cd1f82017903f200eed418649c5"),
                ("= <T121_README_LINES> ]", "= 421 ]"),
                ("<T121_DOCS_VERIFICATION_REPORT_CR_STRIPPED_DIGEST_64HEX>", "7ace2eb5785087af51c00179fb61a43fbf8011de533f1cb91351be961883cd2a")]:
    settled = settled.replace(ph, val)
if settled == cmd:
    fail.append("the settled form equals the shipped command - the amendment would be a no-op dressed as a fix")
if "<T121_" in settled:
    fail.append("placeholders survive substitution - the protocol is incomplete")
if fail:
    sys.stdout.write("ac4 evidence: " + "; ".join(fail) + "\n")
    print("ac4 RED: the leg-227 amendment record is not sound (%d defects above)" % len(fail))
    raise SystemExit(1)
sys.stdout.write("ac4 evidence: amendment PROPOSED against the e98f96bd index; old/new command shas and before/after entry shas reconstruct; 3 regions unique + reverse-lossless; settled form differs from shipped; card writes zero index bytes\n")
PYEOF
echo "ac4 GREEN: the leg-227 gate amendment is a sound, reconstructible, PROPOSED record"
